        // metoda vyvolání uložení akce
        UlozAkci () {
            var cislo = this.globals.Te1_Msk_Nula;
            var that = this;
            var $cDiv = $(this.contentDiv);
            //this.contentDiv.showFlash({ label: 'Ukladam akci ' + cislo });
            if ($cDiv.findForms().gform("isValid", true)) {
                //var dto = {};
                $cDiv.findForms((["form_zaklad", Gordic.Eko.HeaderForm.Name]).join(",")).findFields().gfield("model", "collect", this.model);
                $cDiv.findFields().gfield("confirm");

                this.model.vlastnosti = Gordic.PopisneVlastnosti.collectValues(this);
 
//                this.model.adresa1 = this.model.adresa.ulice;
                // jeste prepisu hodmnty z pomocnych DTO (fin a real)
                var newDtoIntervalFin: GIntervalDto<number> = { start: 0, end: 0 };
                newDtoIntervalFin.start = this.dto.fin_od!;
                newDtoIntervalFin.end = this.dto.fin_do!;

                var newDtoIntervalReal: GIntervalDto<number> = { start: 0, end: 0 };
                newDtoIntervalReal.start = this.dto.real_od!;
                newDtoIntervalReal.end = this.dto.real_do!;

                var newDtoIntervalObdobi = { interval_fin: newDtoIntervalFin, interval_real: newDtoIntervalReal };

                $cDiv.findForms("HlavniForm_Obdobi").findFields().gfield("model", "collect", newDtoIntervalObdobi);

                this.model.fin_od = newDtoIntervalObdobi.interval_fin.start;
                this.model.fin_do = newDtoIntervalObdobi.interval_fin.end;
                this.model.real_od = newDtoIntervalObdobi.interval_real.start;
                this.model.real_do = newDtoIntervalObdobi.interval_real.end;

                
                //that.actions.actAdaAkceDokladUlozAkci!.setPending(0);

                let prom_vysledek =
                    this.call("Kontrola", { dto: this.model }).then((retVal) => {
                        //kontrola dopadla -> nedělat nic, pokračujeme dále v done
                        if (retVal.vysledek == false) {
                            return this.dialogs.confirm("Položka plánu má vyplněný Věcný profil nebo Rozpis zdrojů, bez vyplněných Plánovaných výdajů. Opravdu chcete položku uložit?").createDialogPromise("yes");
                        }
                        else {
                            return retVal
                        }
                    }).then(() => {

                        //kontrola dopadla, nebo dotaz dopadl -> uložit
                        return this.call("Save", { dto: this.model })
                            .done(function (out_data) {
                                that.trigger("ada_saveakce", [{ data: { cislo: that.cislo } }]);
                                that.trigger("ada_saveakce", [{ data: { cislo: out_data.cislo } }]);
                                //that.actions.actAdaAkceDokladUlozAkci!.setPending(100);

                                that.form_novaakce = false;
                                that.title = that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Položka plánu " + that.model.cislo : "Akce " + that.model.cislo; //aby se dalo přistoupit z breadcrumbs, je nastaveno zde místo v C#

                                //JI XXX
                                //that.tryClose();
                                that.statusBarStavAZ.update({ caption: out_data.priz_az_s!, customClass: out_data.priz_az == 1 ? "g-state-warning g-state-text" : "g-state-success g-state-text" });
                                that.statusBarStavAZ2.update({ caption: out_data.stav_az_txt!, customClass: out_data.stav_az == 1 ? "g-state-warning g-state-text" : "g-state-success g-state-text" });
                                that.statusBarStavRealizaceAkce.update({ caption: out_data.stav_real_txt!, customClass: (out_data.aktivita == Interface.AktivitaAkceEnum.Aktivni) ? "g-state-success g-state-text" : (out_data.aktivita == Interface.AktivitaAkceEnum.Navrh) ? "g-state-info g-state-text" : "g-state-error g-state-text" });

                                that.load({ cislo: out_data.cislo, ixs_cia: out_data.ixs_cia, nacitat_s_hist: false })
                                    .then(function (out_data) {
                                        if (that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO) {
                                            if ((that.model.fin_od == null) || (that.model.fin_do == null) || (that.model.real_od == null) || (that.model.real_do == null)) {
                                                that.showFlash("Hodnoty období Financonání a Realizace nejsou vyplněny úplně. Proveďte, prosím, kontrolu správnosti!", "warning", "id-flash-kontrola-fin");
                                            }
                                            else {
                                                that.hideFlash("id-flash-kontrola-fin")
                                            }
                                        }
                                    });
                            });
                    });

                that.actions.actAdaAkceDokladUlozAkci!.setPending(prom_vysledek);

                return prom_vysledek;
            }
        }

