        public nastav_menu_stav_realizace(stav_real: number) {
            var that = this;
            if (that.actions) {
                if (((that.globals.Param_Rezim_Vlastnik == true) && (that.model.Permissions?.JsemVlastnik.value == false)) && (that.model.ixs_fun_az != ($.content("main") as any).IxsFunAkt) && (that.model.JsemKompetent == false))
                {
                    if (that.actions.actEvidovat) { that.actions.actEvidovat!.enabled(false); }
                    if (that.actions.actZaplanovat) { that.actions.actZaplanovat!.enabled(false); }
                    if (that.actions.actZkompletovat) { that.actions.actZkompletovat!.enabled(false); }
                    if (that.actions.actSchvalit) { that.actions.actSchvalit!.enabled(false); }
                    if (that.actions.actVratit) { that.actions.actVratit!.enabled(false); }
                    if (that.actions.actPozastavit) { that.actions.actPozastavit!.enabled(false); }
                    if (that.actions.actUkoncit) { that.actions.actUkoncit!.enabled(false); }
                    if (that.actions.actStornovat) { that.actions.actStornovat!.enabled(false); }
                }
                else
                {
                    if (that.actions.actEvidovat) { that.actions.actEvidovat!.enabled(stav_real == Interface.StavRealizaceAkceEnum.Navrh ? true : false); }
                    if (that.actions.actZaplanovat) { that.actions.actZaplanovat!.enabled(stav_real == Interface.StavRealizaceAkceEnum.Evidovano ? true : false); }
                    if (that.actions.actZkompletovat) { that.actions.actZkompletovat!.enabled(stav_real == Interface.StavRealizaceAkceEnum.Zaplanovano ? true : false); }
                    if (that.actions.actSchvalit) { that.actions.actSchvalit!.enabled(stav_real == Interface.StavRealizaceAkceEnum.Zkompletovano ? true : false); }

                    if (that.actions.actVratit) { that.actions.actVratit!.enabled(((stav_real > Interface.StavRealizaceAkceEnum.Evidovano) || (stav_real <= Interface.StavRealizaceAkceEnum.Zpozdeno)) ? true : false); }

                    if (that.actions.actPozastavit) { that.actions.actPozastavit!.enabled(((stav_real >= Interface.StavRealizaceAkceEnum.Schvaleno) && (stav_real <= Interface.StavRealizaceAkceEnum.Zpozdeno)) ? true : false); }
                    if (that.actions.actUkoncit) { that.actions.actUkoncit!.enabled((((stav_real >= Interface.StavRealizaceAkceEnum.Schvaleno) && (stav_real <= Interface.StavRealizaceAkceEnum.Zpozdeno)) || (stav_real == Interface.StavRealizaceAkceEnum.Pozastaveno)) ? true : false); }

                    if (that.actions.actStornovat) { that.actions.actStornovat!.enabled((stav_real != Interface.StavRealizaceAkceEnum.Stornovano) ? true : false); }
                }
            }
        }

        public nastav_menu_stav_az(stav_az: number) {
            var that = this;
            if (that.actions) {
                // debugger;
                if (((that.globals.Param_Rezim_Vlastnik == true) && (that.model.Permissions?.JsemVlastnik.value == false)) && (that.model.ixs_fun_az != ($.content("main") as any).IxsFunAkt) && (that.model.JsemKompetent == false ))
                {
                    if (that.actions.actNezabezpeceno) { that.actions.actNezabezpeceno!.enabled(false); }
                    if (that.actions.actNafinancovano) { that.actions.actNafinancovano!.enabled(false); }
                    if (that.actions.actZahajeno) { that.actions.actZahajeno!.enabled(false); }
                    if (that.actions.actUkonceno) { that.actions.actUkonceno!.enabled(false); }
                    if (that.actions.actZpetAZ) { that.actions.actZpetAZ!.enabled(false); }
                }
                else
                {
                    if (that.actions.actNezabezpeceno) { that.actions.actNezabezpeceno!.enabled(false); }
                    if (that.actions.actNafinancovano) { that.actions.actNafinancovano!.enabled(stav_az == Interface.StavAZAkceEnum.Nezabezepeceno ? true : false); }
                    if (that.actions.actZahajeno) { that.actions.actZahajeno!.enabled(stav_az == Interface.StavAZAkceEnum.Nafinancovano ? true : false); }
                    if (that.actions.actUkonceno) { that.actions.actUkonceno!.enabled(stav_az == Interface.StavAZAkceEnum.Zahajeno ? true : false); }
                    if (that.actions.actZpetAZ) { that.actions.actZpetAZ!.enabled(stav_az != Interface.StavAZAkceEnum.Nezabezepeceno ? true : false); }
                }
                
            }
        }

